var titles2 = [["\u8BC1\u636E\u6982\u89C8", "Evidence overview"], ["\u4F60\u7684\u8BC1\u636E\u7ED3\u6784", "The structure of your evidence"], ["\u8D44\u6E90\u4E0E\u963B\u529B", "Resources and friction"], ["\u7406\u89E3\u4F60\u7684\u51B3\u7B56\u8FC7\u7A0B", "Understanding your decision process"], ["\u60C5\u5883\u4E2D\u7684\u5173\u7CFB", "Relationships in context"], ["\u5DE5\u4F5C\u3001\u5174\u8DA3\u4E0E\u8868\u8FBE", "Work, interests and expression"], ["\u89E3\u8BFB\u4EBA\u683C\u76F8\u5173\u8BC1\u636E", "Reading personality evidence"], ["\u8D22\u52A1\u4E0E\u5916\u90E8\u8BC1\u636E", "Financial and external evidence"], ["\u5F53\u8BC1\u636E\u9047\u89C1\u5F53\u4E0B\u73B0\u5B9E", "When evidence meets current reality"], ["\u4F60\u7684\u5F53\u524D\u6863\u6848\u72B6\u6001", "Your profile today"]];
var domains = {
  ADAPTATION_COPING: ["\u4F60\u7684\u4F5C\u7B54\u8BA9\u5E94\u5BF9\u538B\u529B\u4E0E\u53D8\u5316\u6210\u4E3A\u53EF\u8BA8\u8BBA\u7684\u7ECF\u9A8C\u9886\u57DF\uFF1A\u4F60\u5DF2\u7ECF\u63D0\u4F9B\u4E86\u81EA\u5DF1\u5982\u4F55\u770B\u5F85\u8FD9\u90E8\u5206\u8FD0\u4F5C\u7684\u89C6\u89D2\u3002\u88AB\u6253\u65AD\u540E\u91CD\u65B0\u5B89\u6392\u6B65\u9AA4\uFF0C\u662F\u533A\u5206\u6062\u590D\u8282\u594F\u4E0E\u6301\u7EED\u627F\u53D7\u8D1F\u8377\u7684\u4E00\u5904\u89C2\u5BDF\u70B9\u3002", "Your response makes coping with pressure and change a visible part of your self-view. It gives us your perspective on this area of functioning. Reorganizing steps after an interruption is one place to distinguish recovering your rhythm from sustaining a demanding workload."],
  BODY_LIFESTYLE_STEWARDSHIP: ["\u4F60\u5BF9\u8EAB\u4F53\u7167\u987E\u4E0E\u65E5\u5E38\u8282\u594F\u7684\u770B\u6CD5\u5DF2\u8FDB\u5165\u6863\u6848\u3002\u8FD9\u4F7F\u4F5C\u606F\u3001\u6D3B\u52A8\u4E0E\u5BDF\u89C9\u75B2\u52B3\u80FD\u591F\u6210\u4E3A\u5177\u4F53\u7684\u89C2\u5BDF\u4E3B\u9898\uFF1B\u4F8B\u5982\uFF0C\u53EF\u4EE5\u6BD4\u8F83\u8BA1\u5212\u4E2D\u7684\u8282\u594F\u4E0E\u67D0\u4E00\u5929\u5B9E\u9645\u4FDD\u7559\u4E86\u54EA\u4E9B\u4E60\u60EF\u3002", "Your view of bodily care and daily rhythm is part of the profile. Routines, activity and noticing fatigue become concrete topics to observe\u2014for example, by comparing an intended routine with the habits actually retained on a particular day."],
  COGNITIVE_NAVIGATION: ["\u8FD9\u4E00\u9886\u57DF\u4F7F\u4FE1\u606F\u7406\u89E3\u3001\u63A8\u7406\u4E0E\u843D\u5B9E\u4E4B\u95F4\u7684\u533A\u522B\u53D8\u5F97\u6E05\u695A\u3002\u628A\u4E00\u4E2A\u95EE\u9898\u8BF4\u6E05\u695A\uFF0C\u4E0E\u5728\u5B66\u4E60\u65B0\u4EFB\u52A1\u65F6\u5B8C\u6210\u4E0B\u4E00\u6B65\uFF0C\u662F\u76F8\u4E92\u5173\u8054\u5374\u4E0D\u540C\u7684\u7ECF\u9A8C\uFF1B\u5DF2\u6709\u8BB0\u5F55\u4E3A\u6838\u5BF9\u8FD9\u79CD\u533A\u522B\u63D0\u4F9B\u4E86\u8D77\u70B9\u3002", "This area brings the distinction between understanding information, reasoning and following through into focus. Explaining a problem and completing the next step while learning a new task are related but different experiences. The recorded material offers a starting point for comparing them."],
  EMOTIONAL_SOCIAL_REGULATION: ["\u60C5\u7EEA\u4E0E\u793E\u4EA4\u8C03\u8282\u5DF2\u6210\u4E3A\u4F60\u63CF\u8FF0\u81EA\u5DF1\u7684\u4E00\u4E2A\u89D2\u5EA6\u3002\u5B83\u8BA9\u5BDF\u89C9\u611F\u53D7\u3001\u8868\u8FBE\u9700\u8981\u4E0E\u56DE\u5E94\u4ED6\u4EBA\u80FD\u591F\u5206\u522B\u8BA8\u8BBA\u3002\u5728\u4E00\u6B21\u56F0\u96BE\u5BF9\u8BDD\u4E2D\uFF0C\u53EF\u4EE5\u89C2\u5BDF\u8FD9\u51E0\u6B65\u5982\u4F55\u8854\u63A5\uFF0C\u800C\u4E0D\u628A\u4E00\u6B21\u6574\u4F53\u4F5C\u7B54\u5F53\u6210\u5BF9\u6574\u6BB5\u5173\u7CFB\u7684\u5224\u65AD\u3002", "Emotional and social regulation is one angle through which you describe yourself. It allows noticing feelings, expressing needs and responding to another person to be discussed separately. A difficult conversation can reveal how these steps connect, without making one broad response a verdict on a relationship."],
  FINANCIAL_CAPABILITY: ["\u91D1\u94B1\u4E8B\u52A1\u5728\u5DF2\u6709\u8BC1\u636E\u4E2D\u6709\u81EA\u5DF1\u7684\u4F4D\u7F6E\u3002\u5B83\u4F7F\u201C\u5982\u4F55\u7406\u89E3\u8D22\u52A1\u80FD\u529B\u201D\u6210\u4E3A\u660E\u786E\u95EE\u9898\uFF1A\u89C9\u5F97\u6709\u6240\u51C6\u5907\u3001\u7406\u89E3\u4E00\u4E2A\u539F\u5219\u4E0E\u5B9E\u9645\u6267\u884C\u9009\u62E9\uFF0C\u53EF\u4EE5\u5206\u522B\u6838\u5BF9\u3002\u610F\u5916\u652F\u51FA\u662F\u4E00\u79CD\u53EF\u80FD\u8BA9\u8FD9\u4E9B\u533A\u522B\u663E\u73B0\u7684\u60C5\u5883\u3002", "Money-related demands have a place in the available evidence. They make how you understand financial capability a specific question: feeling prepared, understanding a principle and acting on a choice can be examined separately. An unexpected expense is one possible context in which these distinctions become visible."],
  MEANING_VALUES: ["\u610F\u4E49\u4E0E\u4EF7\u503C\u4E3A\u7406\u89E3\u4F18\u5148\u4E8B\u9879\u63D0\u4F9B\u4E86\u4E00\u4E2A\u5165\u53E3\u3002\u5DF2\u6709\u63CF\u8FF0\u53EF\u4EE5\u4E0E\u5177\u4F53\u53D6\u820D\u5BF9\u7167\uFF1A\u5F53\u65F6\u95F4\u3001\u91D1\u94B1\u6216\u957F\u671F\u627F\u8BFA\u5F7C\u6B64\u7ADE\u4E89\u65F6\uFF0C\u54EA\u4E9B\u8003\u8651\u88AB\u4FDD\u7559\u3001\u54EA\u4E9B\u88AB\u8C03\u6574\u3002\u8FD9\u6837\u7684\u6838\u5BF9\u80FD\u8BA9\u4EF7\u503C\u4ECE\u540D\u79F0\u53D8\u6210\u6709\u60C5\u5883\u7684\u7406\u89E3\u3002", "Meaning and values provide an entry point for understanding priorities. The recorded account can be compared with a concrete trade-off: when time, money or a long-term commitment competes for attention, which considerations are retained and which are adjusted? This makes values a contextual question rather than just a label."]
};
