    const g = cards.filter((c) => re.test(c.domainId + " " + c.facetId));
    return row(zh2, en, g.length ? "\u5DF2\u6709\u76F8\u5173\u4E3B\u9898" : "\u5C1A\u5F85\u89C2\u5BDF", g.length ? "Related topic recorded" : "Awaiting observation", g.map((c) => c.signalRef), g.length ? names(g, "zh-Hans") : "\u672C\u6B21\u8D44\u6599\u6CA1\u6709\u5BF9\u5E94\u8BB0\u5F55", g.length ? names(g, "en") : "No corresponding record in this material");
