  pair(5, social.length ? "\u4F60\u7684\u60C5\u7EEA\u4E0E\u793E\u4EA4\u81EA\u9648\uFF0C\u4E3A\u7406\u89E3\u5173\u7CFB\u4E2D\u7684\u81EA\u5DF1\u63D0\u4F9B\u4E86\u7B2C\u4E00\u4EBA\u79F0\u5165\u53E3\u3002\u5B83\u8BA9\u8868\u8FBE\u611F\u53D7\u3001\u56DE\u5E94\u4ED6\u4EBA\u4E0E\u8C03\u8282\u4E92\u52A8\u6210\u4E3A\u53EF\u4EE5\u7EC6\u5206\u7684\u4E3B\u9898\u3002\u5176\u610F\u4E49\u5728\u4E8E\u770B\u6E05\u4F60\u5982\u4F55\u63CF\u8FF0\u81EA\u5DF1\u7684\u53C2\u4E0E\u65B9\u5F0F\uFF0C\u800C\u4E0D\u662F\u66FF\u53E6\u4E00\u4E2A\u4EBA\u8BF4\u660E\u4ED6\u4EEC\u5982\u4F55\u4F53\u9A8C\u4F60\u3002" : "\u5F53\u524D\u4E2A\u4EBA\u8D44\u6599\u4E3A\u7406\u89E3\u4E92\u52A8\u4E2D\u7684\u81EA\u5DF1\u63D0\u4F9B\u4E86\u76F8\u5E94\u7684\u81EA\u6211\u6216\u6D4B\u8BC4\u89C6\u89D2\u3002\u53EF\u4EE5\u4ECE\u4E00\u4E2A\u5177\u4F53\u95EE\u9898\u5F00\u59CB\uFF1A\u5728\u534F\u4F5C\u6216\u56F0\u96BE\u5BF9\u8BDD\u4E2D\uFF0C\u54EA\u4E9B\u90E8\u5206\u4E0E\u6765\u6E90\u63CF\u8FF0\u6709\u5173\uFF0C\u54EA\u4E9B\u5C5E\u4E8E\u53CC\u65B9\u5171\u540C\u53D1\u751F\u7684\u8FC7\u7A0B\uFF1F", social.length ? "Your emotional and social self-report offers a first-person entry point into understanding yourself in relationships. Expressing feelings, responding to others and regulating an exchange become topics that can be examined separately. Its contribution is to clarify how you describe your participation, rather than speak for another person\u2019s experience of you." : "The current personal material offers its own self-view or assessment perspective for understanding interaction. A concrete question is where a source account relates to collaboration or a difficult conversation, and which parts belong to what happened between both people.", social.length ? social.map((c) => c.signalRef) : refs, "RELATIONSHIP_SCOPE");
  pair(5, rel.length ? "\u5173\u7CFB\u8865\u5145\u8D44\u6599\u8BA9\u4E24\u4EFD\u72EC\u7ACB\u81EA\u6211\u63CF\u8FF0\u80FD\u591F\u5E76\u6392\u9605\u8BFB\u3002\u8FD9\u53EF\u4EE5\u5E2E\u52A9\u63D0\u51FA\u4E00\u4E2A\u5171\u540C\u6838\u5BF9\u7684\u95EE\u9898\uFF1A\u540C\u4E00\u4E92\u52A8\u4E2D\uFF0C\u4E24\u4E2A\u4EBA\u5206\u522B\u6CE8\u610F\u5230\u4EC0\u4E48\uFF1F\u5982\u679C\u8D44\u6599\u53EA\u662F\u5404\u81EA\u7684\u81EA\u9648\uFF0C\u5C31\u4ECD\u9700\u4E0E\u5BF9\u65B9\u5BF9\u4F60\u7684\u89C2\u5BDF\u3001\u5171\u540C\u4E8B\u4EF6\u548C\u5173\u7CFB\u6761\u4EF6\u5206\u522B\u4FDD\u5B58\u3002" : "\u4E00\u6B21\u56F0\u96BE\u5BF9\u8BDD\u53EF\u4EE5\u4F5C\u4E3A\u89C2\u5BDF\u5165\u53E3\uFF1A\u4F60\u600E\u6837\u63CF\u8FF0\u81EA\u5DF1\u7684\u53CD\u5E94\uFF0C\u5BF9\u65B9\u5B9E\u9645\u8BF4\u4E86\u4EC0\u4E48\uFF0C\u4EE5\u53CA\u53CC\u65B9\u5728\u4EC0\u4E48\u6761\u4EF6\u4E0B\u4E92\u52A8\u3002\u628A\u8FD9\u51E0\u79CD\u8D44\u6599\u5206\u5F00\u8BB0\u5F55\uFF0C\u4F1A\u6BD4\u7528\u5355\u4E00\u5173\u7CFB\u6807\u7B7E\u66F4\u6E05\u695A\u5730\u5448\u73B0\u81EA\u5DF1\u7684\u4F4D\u7F6E\u3002", rel.length ? "The relationship companion lets two independent self-accounts be read alongside one another. This frames a shared question: what did each person notice in the same exchange? When the material consists of separate self-reports, it remains distinct from another person\u2019s observations of you, a shared event and relationship conditions." : "A difficult conversation can be an observation point: how you describe your response, what the other person actually said and the conditions of the exchange. Recording these separately gives a clearer view of your position than a single relationship label.", rel.length ? uniq(rel.flatMap((x) => [x.id, ...arr(x.signalRefs)])) : refs, "CONDITIONAL_CONTEXT");
